interface IconProps {
  size?: number | string;
  strokeWidth?: number | string;
  absoluteStrokeWidth?: boolean;
}

function createIcon(key: string) {
  return defineComponent({
    name: `Fluent${key}`,
    inheritAttrs: false,
    props: {
      size: { type: [Number, String], default: 24 },
      strokeWidth: { type: [Number, String], default: undefined },
      absoluteStrokeWidth: { type: Boolean, default: false },
    },
    setup(props: IconProps, { attrs }) {
      return () =>
        h('svg', {
          ...attrs,
          xmlns: 'http://www.w3.org/2000/svg',
          viewBox: '0 0 24 24',
          width: props.size,
          height: props.size,
          fill: 'currentColor',
          focusable: 'false',
          'aria-hidden': (attrs as Record<string, unknown>)['aria-hidden'] ?? 'true',
          innerHTML: inner[key],
        });
    },
  });
}

